package com.hibernate.ecommerce.mapper;import com.hibernate.ecommerce.dto.ClientDTO;import com.hibernate.ecommerce.model.Client;public class ClientMapper {    public static ClientDTO toDTO(Client client){        if(client == null) return null;        return ClientDTO.builder()                .id(client.getId())                .name(client.getName())                .phone(client.getPhone())                .email(client.getEmail())                .build();    }    public static Client toEntity(ClientDTO dto){        if(dto == null) return null;        return Client.builder()                .id(dto.getId())                .name(dto.getName())                .phone(dto.getPhone())                .email(dto.getEmail())                .build();    }}